import { describe, expect, it } from 'vitest';
import { forever, generate, num } from '../helpers';

describe('sound blocks', () => {
  it('plays a tone and silences the buzzer afterwards', () => {
    const code = generate([
      forever({
        type: 'buzz',
        fields: { PIN: '15' },
        inputs: { FREQ: num(440), MS: num(200) },
      }),
    ]);
    expect(code).toBe(
      [
        '# Code automatically generated by PicoBlocks',
        'from machine import Pin, PWM',
        'import time',
        '',
        'pwm_15 = PWM(Pin(15))',
        '',
        'while True:',
        '    pwm_15.freq(440)',
        '    pwm_15.duty_u16(32768)',
        '    time.sleep_ms(200)',
        '    pwm_15.duty_u16(0)',
        '',
      ].join('\n'),
    );
  });

  it('shares one PWM object when a pin both buzzes and fades', () => {
    const code = generate([
      forever(
        { type: 'buzz', fields: { PIN: '15' }, inputs: { FREQ: num(880), MS: num(50) } },
        { type: 'pwm_write', fields: { PIN: '15' }, inputs: { DUTY: num(1000) } },
      ),
    ]);
    expect(code.match(/pwm_15 = PWM/g)).toHaveLength(1);
  });

  it('coerces a computed frequency to an int', () => {
    const code = generate([
      forever({
        type: 'buzz',
        fields: { PIN: '15' },
        inputs: {
          FREQ: {
            block: {
              type: 'math_arithmetic',
              fields: { OP: 'DIVIDE' },
              inputs: { A: num(2000), B: num(3) },
            },
          },
          MS: num(100),
        },
      }),
    ]);
    expect(code).toContain('    pwm_15.freq(int(2000 / 3))');
  });
});
